        if side == 'top':
            cells = [(r, lane) for r in range(1, h)]
        elif side == 'bottom':
            cells = [(r, lane) for r in range(h - 2, -1, -1)]
        elif side == 'left':
            cells = [(lane, c) for c in range(1, w)]
        else:  # right
            cells = [(lane, c) for c in range(w - 2, -1, -1)]
        for r, c in cells:
            if target == (r, c):
                out[r][c] = 4
                return
            out[r][c] = ink

    # Equal-length opposing edge segments pair by offset. A marker in one
    # segment sends a ray from that edge to the marker and a full ray from the
    # corresponding offset on the opposite segment.
    for side_a, side_b in (('top', 'bottom'), ('left', 'right')):
        for a0, a1, _ in edges[side_a]:
            for b0, b1, _ in edges[side_b]:
                if a1 - a0 != b1 - b0:
                    continue
                for r, c in markers:
                    pos = c if side_a == 'top' else r
                    if a0 <= pos < a1:
                        paired = b0 + (pos - a0)
                        inward_ray(side_a, pos, (r, c))
                        inward_ray(side_b, paired)
                    elif b0 <= pos < b1:
                        paired = a0 + (pos - b0)
                        inward_ray(side_b, pos, (r, c))
                        inward_ray(side_a, paired)
    return out
