                i += 1
                continue
            j = i + 1
            while j < len(vals) and vals[j] == vals[i]:
                j += 1
            if j - i >= 2:
                ans.append((i, j, vals[i]))
            i = j
        return ans

    edges = {
        'top': runs(grid[0]),
        'bottom': runs(grid[-1]),
        'left': runs([grid[r][0] for r in range(h)]),
        'right': runs([grid[r][-1] for r in range(h)]),
    }
    frame_colors = {col for seq in edges.values() for _, _, col in seq}
    counts = Counter(v for row in grid for v in row)
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] not in frame_colors]
    if not markers:
        return out
    ink = grid[markers[0][0]][markers[0][1]]
    markers = [(r, c) for r, c in markers if grid[r][c] == ink]

    def paired_lines(side_a, side_b):
        for a0, a1, _ in edges[side_a]:
            for b0, b1, _ in edges[side_b]:
                if a1 - a0 != b1 - b0:
                    continue
                for r, c in markers:
                    pos = c if side_a in ('top', 'bottom') else r
                    if a0 <= pos < a1:
                        offset = pos - a0
                        launch_from(side_a, pos, (r, c))
                        launch_from(side_b, b0 + offset)
                    elif b0 <= pos < b1:
                        offset = pos - b0
                        launch_from(side_b, pos, (r, c))
                        launch_from(side_a, a0 + offset)

    def launch_from(side, lane, target=None):
        if side == 'top':
            cells = [(rr, lane) for rr in range(1, h-1)]
        elif side == 'bottom':
            cells = [(rr, lane) for rr in range(h-2, 0, -1)]
        elif side == 'left':
